const files = $input.all().map(i => i.json);

if (files.length === 0) {
  return [];
}

// Carry workflow variables forward by grabbing them from Node 2
const config = $('Edit Fields1').first().json;

// Sort oldest first
files.sort((a, b) => new Date(a.createdTime) - new Date(b.createdTime));
const oldest = files[0];

return [{
  json: {
    file_id: oldest.id,
    file_name: oldest.name,
    file_size: oldest.size,
    file_mime_type: oldest.mimeType,
    created_time: oldest.createdTime,
    client_id: config.client_id,
    client_slug: config.client_slug,
    ingestion_type: config.ingestion_type,
    intake_folder_id: config.intake_folder_id,
    completed_folder_id: config.completed_folder_id,
  }
}];

const fromWebhook = $('Normalize Webhook File').isExecuted;
const meta = fromWebhook
  ? $('Normalize Webhook File').first().json
  : $('Loop Over Items').item.json;
const rawText = String($input.first().json.data || '').trim();
if (!rawText) throw new Error(`Empty file: ${meta.file_name}`);

const fallbackId = meta.file_name
  .replace(/\.txt$/i, '')
  .replace(/[\s\-_]*(transcript|summary)\s*$/i, '')
  .trim();

return [{ json: {
  ...meta,
  source_video_id: fallbackId,
  title: fallbackId.replace(/[-_]+/g, ' ').trim(),
  source_file: `${fallbackId}.mp4`,
  raw_text: rawText,
  word_count_total: rawText.split(/\s+/).length
} }];

const item = $input.first().json;
const TARGET_WORDS = 600;
const OVERLAP_WORDS = 100;
const MAX_CHUNKS = 500;

const rawText = item.raw_text;

function timestampToSeconds(h, m, s) {
  if (s !== undefined && s !== null) {
    return parseInt(h, 10) * 3600 + parseInt(m, 10) * 60 + parseInt(s, 10);
  }
  return parseInt(h, 10) * 60 + parseInt(m, 10);
}

// Find all timestamp positions in the raw text
const matches = [];
const re = /\[(\d{1,2}):(\d{2})(?::(\d{2}))?\]/g;
let m;
while ((m = re.exec(rawText)) !== null) {
  matches.push({
    pos: m.index,
    seconds: timestampToSeconds(m[1], m[2], m[3]),
    fullMatch: m[0],
  });
}

const hasTimestamps = matches.length > 0;

// No timestamps — fall back to plain word chunking
if (!hasTimestamps) {
  const words = rawText.split(/\s+/).filter(Boolean);
  const chunks = [];
  let cursor = 0;
  let chunkIndex = 0;

  while (cursor < words.length) {
    const targetEnd = Math.min(cursor + TARGET_WORDS, words.length);
    const chunkWords = words.slice(cursor, targetEnd);
    if (chunkWords.length === 0) break;

    chunks.push({
      chunk_index: chunkIndex,
      start_seconds: 0,
      end_seconds: 0,
      speaker: null,
      transcript_text: chunkWords.join(' '),
      word_count: chunkWords.length,
    });

    chunkIndex++;
    const nextCursor = targetEnd - OVERLAP_WORDS;
    if (nextCursor <= cursor) break;
    cursor = nextCursor;
  }

  return [{
    json: {
      ...item,
      has_timestamps: false,
      summary_text: null,
      topics: [],
      is_auto_summary: false,
      chunks,
      embedding_inputs: chunks.map(c => c.transcript_text),
    }
  }];
}

// Build segments — keep the timestamp marker WITH the text that follows
const segments = [];
for (let i = 0; i < matches.length; i++) {
  const startPos = matches[i].pos;                    // ← include the timestamp
  const endPos = i + 1 < matches.length ? matches[i + 1].pos : rawText.length;
  const text = rawText.slice(startPos, endPos).trim();
  if (text.length === 0) continue;

  segments.push({
    start_seconds: matches[i].seconds,
    end_seconds: i + 1 < matches.length ? matches[i + 1].seconds : matches[i].seconds,
    text,
  });
}

// Group segments into chunks of ~TARGET_WORDS
const chunks = [];
let currentText = [];
let currentWords = 0;
let currentStart = segments[0].start_seconds;
let currentEnd = segments[0].end_seconds;
let chunkIndex = 0;
let segIdx = 0;

function countWords(s) {
  // Count actual words, not timestamp markers
  return s.replace(/\[\d{1,2}:\d{2}(?::\d{2})?\]/g, '')
          .split(/\s+/)
          .filter(Boolean).length;
}

while (segIdx < segments.length) {
  const seg = segments[segIdx];
  const segWordCount = countWords(seg.text);

  if (currentWords + segWordCount > TARGET_WORDS && currentWords > 0) {
    chunks.push({
      chunk_index: chunkIndex,
      start_seconds: currentStart,
      end_seconds: currentEnd,
      speaker: null,
      transcript_text: currentText.join(' ').replace(/\s+/g, ' ').trim(),
      word_count: currentWords,
    });
    chunkIndex++;

    // Rewind for overlap
    let overlapWords = 0;
    let overlapStart = segIdx;
    while (overlapStart > 0 && overlapWords < OVERLAP_WORDS) {
      overlapStart--;
      overlapWords += countWords(segments[overlapStart].text);
    }
    segIdx = overlapStart;
    currentText = [];
    currentWords = 0;
    currentStart = segments[segIdx].start_seconds;
    continue;
  }

  currentText.push(seg.text);
  currentWords += segWordCount;
  currentEnd = seg.end_seconds;
  segIdx++;
}

if (currentText.length > 0) {
  chunks.push({
    chunk_index: chunkIndex,
    start_seconds: currentStart,
    end_seconds: currentEnd,
    speaker: null,
    transcript_text: currentText.join(' ').replace(/\s+/g, ' ').trim(),
    word_count: currentWords,
  });
}

if (chunks.length > MAX_CHUNKS) {
  throw new Error(`Too many chunks (${chunks.length}) for ${item.file_name}`);
}

return [{
  json: {
    ...item,
    has_timestamps: true,
    summary_text: null,
    topics: [],
    is_auto_summary: false,
    chunks,
    embedding_inputs: chunks.map(c => c.transcript_text),
  }
}];

const item = $input.first().json;

return [{
  json: {
    ...item,
    has_timestamps: false,
    summary_text: item.raw_text,
    topics: [],
    is_auto_summary: false,
    chunks: [],
    embedding_inputs: [item.raw_text],
  }
}];

const apiResponse = $input.first().json;
const identity = $('Resolve Ingestion Manifest').item.json;
const parent = identity.ingestion_type === 'transcripts'
  ? $('Chunk transcripts').item.json
  : $('Prepare summaries').item.json;
const embeddings = apiResponse?.data;
if (!Array.isArray(embeddings) || embeddings.length === 0) {
  throw new Error('Missing embeddings in OpenAI response');
}
const fmt = arr => arr ? `[${arr.join(',')}]` : null;
let summary_embedding = null;
let chunkEmbeddings = embeddings;
if (parent.ingestion_type === 'summaries') {
  summary_embedding = fmt(embeddings[0].embedding);
  chunkEmbeddings = [];
}
let chunks_with_embeddings = [];
if (parent.chunks?.length) {
  if (chunkEmbeddings.length !== parent.chunks.length) {
    throw new Error(`Chunk embedding mismatch: got ${chunkEmbeddings.length}, expected ${parent.chunks.length}`);
  }
  chunks_with_embeddings = parent.chunks.map((chunk, index) => ({
    ...chunk,
    embedding: fmt(chunkEmbeddings[index].embedding)
  }));
}
return [{ json: {
  client_id: parent.client_id,
  source_video_id: parent.source_video_id,
  title: parent.title,
  source_file: parent.source_file,
  b2_path: parent.b2_path || null,
  thumbnail_b2_path: parent.thumbnail_b2_path || null,
  has_timestamps: parent.has_timestamps,
  summary_text: parent.summary_text || null,
  summary_embedding,
  topics: parent.topics?.length ? parent.topics : null,
  is_auto_summary: parent.is_auto_summary,
  chunks: chunks_with_embeddings,
  file_id: parent.file_id,
  file_name: parent.file_name,
  completed_folder_id: parent.completed_folder_id,
  ingestion_type: parent.ingestion_type
} }];

const parent = $('format embeddings').first().json;
const summaryId = $input.first().json.summary_id;

if (!parent.chunks || parent.chunks.length === 0) {
  return [];
}

return parent.chunks.map(chunk => ({
  json: {
    client_id: parent.client_id,
    source_video_id: parent.source_video_id,
    summary_id: summaryId,
    chunk_index: chunk.chunk_index,
    start_seconds: chunk.start_seconds,
    end_seconds: chunk.end_seconds,
    speaker: chunk.speaker,
    transcript_text: chunk.transcript_text,
    embedding: chunk.embedding,
    word_count: chunk.word_count,
  }
}));

